def normalize_expense(expense):
    normalized_expense = {
        "vendor": expense['vendor'],
        "date": expense['date'],
        "total": expense['total'],
        "items": expense['items']
    }
    return normalized_expense

def validate_document_fields(document):
    required_fields = ['vendor', 'date', 'total', 'items']
    for field in required_fields:
        if field not in document or not document[field]:
            return False
    return True

import os
from google.cloud import documentai

def get_client():
    return documentai.DocumentProcessorServiceClient()

def get_project_id():
    return os.getenv('GOOGLE_CLOUD_PROJECT')

def get_location():
    return 'us'

def get_processor_id():
    return os.getenv('DOCUMENTAI_PROCESSOR_ID')

def create_request(project_id, location, processor_id, file_path):
    with open(file_path, "rb") as image:
        image_content = image.read()

    raw_document = {"content": image_content, "mime_type": 'application/pdf'}
    document = {"raw_document": raw_document}
    request = {"name": f'projects/{project_id}/locations/{location}/processors/{processor_id}', "document": document}
    return request

def parse_response(response):
    document = response.document
    fields = {}
    for field in document.fields:
        fields[field.field_name] = field.value.string_value
    return fields

def summarize_invoice_fields(vendor, date, total, items):
    summary = f'Invoice from {vendor} on {date} for a total of {total}. Items: {items}'
    return summary

from google.cloud import firestore

def store_expense_record(expense):
    db = firestore.Client()
    doc_ref = db.collection(u'expenses').document()
    doc_ref.set({
        'vendor': expense['vendor'],
        'date': expense['date'],
        'total': expense['total'],
        'items': expense['items']
    })
